#include <stdio.h>

int main(void) {
    int a = 17, b = 5;
    printf("%d %d\n", a / b, a % b);
    printf("%d %d %d\n", -17 / 5, -17 % 5, 17 % -5);
    printf("%.2f %d\n", (float)a / b, 7 / 2 * 2);
    int x = 5, y;
    y = x++ + 10;               /* use x, then increment */
    printf("%d %d\n", x, y);
    y = ++x * 2;                /* increment x, then use */
    printf("%d %d\n", x, y);
    int k = (x = 3, x + 4);     /* comma operator: value of last operand */
    printf("%d\n", k);
    printf("%d %d %d\n", 012, 0x1F, 'A');   /* octal, hex, char code */
    printf("%d %d %d\n", 6 & 3, 6 | 3, 6 ^ 3);
    printf("%d %d %d\n", 1 << 4, 40 >> 3, ~5);
    int i = 0, j = 0;
    if (i++ && j++) { }         /* short-circuit: j++ never runs */
    printf("%d %d\n", i, j);
    printf("%d\n", 10 > 5 ? 100 : 200);
    return 0;
}

#include <stdio.h>

int main(void) {
    int n = 2;
    switch (n) {
        case 1:  printf("one\n");
        case 2:  printf("two\n");      /* execution starts here */
        case 3:  printf("three\n");    /* falls through: no break above */
                 break;
        default: printf("other\n");
    }

    int i, sum = 0;
    for (i = 1; i <= 10; i++) {
        if (i % 2 == 0) continue;      /* skip even numbers */
        if (i > 7) break;              /* leave loop when i = 9 */
        sum += i;                      /* 1 + 3 + 5 + 7 */
    }
    printf("sum = %d, i = %d\n", sum, i);

    int j = 10;
    do {
        printf("do-while body runs once, j = %d\n", j);
    } while (j < 5);

    int count = 0;
    for (i = 0; i < 5; i++)
        for (j = i; j < 5; j++)
            count++;
    printf("count = %d\n", count);
    return 0;
}

#include <stdio.h>

void swapv(int a, int b) { int t = a; a = b; b = t; }      /* call by value */
void swapr(int *a, int *b) { int t = *a; *a = *b; *b = t; } /* via pointers */

int counter(void) {
    static int c = 0;   /* initialised once, keeps its value between calls */
    c++;
    return c;
}

int main(void) {
    int x = 1, y = 2;
    swapv(x, y);
    printf("%d %d\n", x, y);
    swapr(&x, &y);
    printf("%d %d\n", x, y);
    counter();
    counter();
    printf("%d\n", counter());
    return 0;
}

#include <stdio.h>

long fact(int n) { return n <= 1 ? 1 : n * fact(n - 1); }
int fib(int n)   { return n < 2 ? n : fib(n - 1) + fib(n - 2); }

void show(int n) {
    if (n == 0) return;          /* base case */
    printf("%d", n);             /* before the recursive call */
    show(n - 1);
    printf("%d", n);             /* after the call: runs while unwinding */
}

int main(void) {
    printf("%ld %d\n", fact(5), fib(7));
    show(3);
    printf("\n");
    return 0;
}

#include <stdio.h>
#include <string.h>

int main(void) {
    int a[5] = {10, 20};                 /* remaining elements become 0 */
    printf("%d %d %d\n", a[1], a[4], (int)(sizeof a / sizeof a[0]));

    int m[2][3] = {{1, 2, 3}, {4, 5, 6}};
    printf("%d %d\n", m[1][2], *(*(m + 1) + 0));

    char s[20] = "Delhi";
    printf("%d %d\n", (int)strlen(s), (int)sizeof(s));
    char t[] = "DSSSB";                   /* 5 chars + '\0' */
    printf("%d %d\n", (int)strlen(t), (int)sizeof(t));

    strcat(s, " TGT");
    printf("%s %d\n", s, (int)strlen(s));
    printf("%d %d\n", strcmp("abc", "abd") < 0, strcmp("CS", "CS"));
    strcpy(t, "CS");
    printf("%s\n", t);
    return 0;
}

#include <stdio.h>

int main(void) {
    int a[] = {5, 10, 15, 20};
    int *p = a;                   /* same as &a[0] */
    printf("%d %d\n", *p, *(p + 2));
    p++;                          /* now points to a[1] */
    printf("%d %d\n", *p, p[1]);
    printf("%d\n", (int)(&a[3] - p));   /* elements between pointers */
    printf("%d\n", *p++);         /* prints a[1], then p -> a[2] */
    printf("%d\n", ++*p);         /* a[2] becomes 16 */
    int x = 7, *q = &x, **r = &q;
    **r = 9;                      /* changes x through two levels */
    printf("%d %d\n", x, *q);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n = 5, i, sum = 0;
    int *arr = (int *)malloc(n * sizeof(int));     /* garbage values */
    if (arr == NULL) return 1;
    for (i = 0; i < n; i++) {
        arr[i] = (i + 1) * (i + 1);
        sum += arr[i];
    }
    printf("sum of squares = %d\n", sum);

    int *z = (int *)calloc(3, sizeof(int));        /* zero-initialised */
    if (z == NULL) { free(arr); return 1; }
    printf("%d %d %d\n", z[0], z[1], z[2]);

    int *tmp = (int *)realloc(arr, 10 * sizeof(int)); /* grow block */
    if (tmp != NULL) arr = tmp;
    printf("%d\n", arr[4]);                        /* old data kept */

    free(arr);
    free(z);
    arr = NULL;                                    /* avoid dangling */
    return 0;
}

#include <stdio.h>
#include <string.h>

struct student {
    int roll;
    char name[20];
    float marks;
};

typedef struct { int x, y; } Point;

union data {
    int i;
    char c;
};

enum color { RED, GREEN = 5, BLUE };

int main(void) {
    struct student s = {101, "Asha", 88.5f};
    struct student *ps = &s;
    printf("%d %s %.1f\n", s.roll, ps->name, (*ps).marks);

    struct student s2 = s;            /* structures can be assigned */
    strcpy(s2.name, "Ravi");
    printf("%s %s\n", s.name, s2.name);

    Point p = {3, 4};
    printf("%d\n", p.x * p.x + p.y * p.y);

    union data d;
    d.i = 300;
    d.c = 'Z';                         /* overwrites shared memory */
    printf("%c\n", d.c);

    printf("%d %d %d\n", RED, GREEN, BLUE);
    return 0;
}

#include <stdio.h>

int main(void) {
    FILE *fp = fopen("marks.txt", "w");      /* create / truncate */
    if (fp == NULL) return 1;
    fprintf(fp, "%d %d %d\n", 70, 85, 90);
    fclose(fp);

    fp = fopen("marks.txt", "a");            /* append at end */
    if (fp == NULL) return 1;
    fputs("95\n", fp);
    fclose(fp);

    int v, total = 0, n = 0;
    fp = fopen("marks.txt", "r");            /* read */
    if (fp == NULL) return 1;
    while (fscanf(fp, "%d", &v) == 1) {
        total += v;
        n++;
    }
    fclose(fp);
    printf("%d values, total = %d\n", n, total);
    return 0;
}

#include <stdio.h>
#define SQUARE(x) x * x            /* unsafe: no parentheses */
#define SQ(x) ((x) * (x))          /* safe version */
#define MAX(a, b) ((a) > (b) ? (a) : (b))
#define DEBUG

int main(void) {
    printf("%d %d\n", SQUARE(2 + 3), SQ(2 + 3));
    printf("%d %d\n", 100 / SQUARE(5), 100 / SQ(5));
    printf("%d\n", MAX(4, 9));
#ifdef DEBUG
    printf("debug build\n");
#else
    printf("release build\n");
#endif
    return 0;
}

